"use strict";(self.webpackChunkdatabricks_monolith=self.webpackChunkdatabricks_monolith||[]).push([[42994],{42994:e=>{e.exports="# Writing Unit Tests for Databricks Python Code\n\nUse this skill when the user asks you to generate, write, or create unit tests for Python code, including PySpark transformations.\n\n## Test Framework Requirements\n\n**IMPORTANT: You MUST use pytest as the testing framework. Do NOT use unittest.**\n\n- Use pytest fixtures for setup/teardown instead of unittest's setUp/tearDown.\n- Use pytest assertions (`assert` statements) instead of `self.assertEqual`, `self.assertTrue`, etc.\n- Use `pytest.raises` for exception testing instead of `self.assertRaises`.\n\n## General Guidelines\n\n- Prefer using PySpark's built-in dataframe testing utilities for comparing expected vs actual output.\n- Use fixtures to manage Spark session setup and teardown when Spark execution is required by the test.\n- Write code as if you are generating a new Python file — include all imports needed to run the file.\n- Give a short explanation of what each test verifies; do not repeat the guidelines back to the user.\n- Always use the createAsset tool to create new test files.\n"}}]);
